mapper.select:
select * from zhfk_notice where
JSON_CONTAINS(`data_scope`->'$.users', concat('[\"',#{dto.userId},'\"]'), '$')

    and read_status = #{dto.needRead}


    and gmt_create >= #{dto.createStart}


    and #{dto.createEnd} >= gmt_create


    and title like concat('%',#{dto.title},'%')


    and JSON_CONTAINS(`biz_info`->'$.bizCode', concat('\"',#{dto.bizType},'\"'), '$')


    and `type` = #{dto.type}


order by gmt_create desc
